use std::fs::File;
use std::io::{self, BufRead, BufReader, Read};
use std::path::{Path, PathBuf};
use clap::Parser;
use regex::Regex;
use walkdir::WalkDir;

#[derive(Parser, Debug)]
#[command(name = "rg", about = "A simplified ripgrep clone")]
struct Args {
    pattern: String,
    #[arg(value_name = "PATH")]
    paths: Vec<PathBuf>,

    #[arg(short = 'n', long)]
    line_number: bool,

    #[arg(short = 'i', long)]
    ignore_case: bool,

    #[arg(short = 'v', long)]
    invert_match: bool,

    #[arg(short = 'w', long)]
    word_regexp: bool,

    #[arg(short = 'l', long)]
    files_with_matches: bool,

    #[arg(short = 'u', action = clap::ArgAction::Count)]
    unrestricted: u8,
}

fn main() -> anyhow::Result<()> {
    let args = Args::parse();

    let mut pattern = args.pattern.clone();
    if args.word_regexp {
        pattern = format!(r"\b{}\b", pattern);
    }

    let mut builder = regex::RegexBuilder::new(&pattern);
    builder.case_insensitive(args.ignore_case);
    let re = builder.build()?;

    let paths = if args.paths.is_empty() {
        vec![PathBuf::from(".")]
    } else {
        args.paths
    };

    for path in paths {
        if path.is_file() {
            search_file(&path, &re, &args)?;
        } else {
            for entry in WalkDir::new(path)
                .into_iter()
                .filter_entry(|e| !is_hidden(e) || args.unrestricted >= 2)
                .filter_map(|e| e.ok()) {
                if entry.file_type().is_file() {
                    search_file(entry.path(), &re, &args)?;
                }
            }
        }
    }

    Ok(())
}

fn is_hidden(entry: &walkdir::DirEntry) -> bool {
    entry.file_name()
         .to_str()
         .map(|s| s.starts_with('.') && s != "." && s != "..")
         .unwrap_or(false)
}

fn search_file(path: &Path, re: &Regex, args: &Args) -> anyhow::Result<()> {
    let file = File::open(path)?;

    // Simple binary detection: check first 1024 bytes for null byte
    let mut buffer = [0u8; 1024];
    let n = (&file).read(&mut buffer)?;
    if args.unrestricted < 3 && buffer[..n].contains(&0) {
        // It's a binary file
        // For simplicity, we just return for now
        // Original rg says "binary file matches" if it matches
        return Ok(());
    }

    let file = File::open(path)?; // Re-open to start from beginning
    let reader = BufReader::new(file);

    let mut matched = false;
    for (idx, line) in reader.lines().enumerate() {
        let line = match line {
            Ok(l) => l,
            Err(_) => continue, // Skip lines that are not valid UTF-8
        };

        let is_match = re.is_match(&line);
        if is_match != args.invert_match {
            matched = true;
            if args.files_with_matches {
                println!("{}", path.display());
                return Ok(());
            }

            let line_num = if args.line_number {
                format!("{}:", idx + 1)
            } else {
                "".to_string()
            };

            println!("{}:{}{}", path.display(), line_num, line);
        }
    }

    Ok(())
}
EOF
