use std::fs::{self, File};
use std::io::{self, BufRead, BufReader, Read, Write};
use std::path::{Path, PathBuf};
use clap::Parser;
use regex::Regex;
use walkdir::WalkDir;

#[derive(Parser, Debug)]
#[command(name = "rg", about = "A simplified ripgrep clone")]
struct Args {
    #[arg(value_name = "PATTERN")]
    pattern: Option<String>,

    #[arg(short = 'e', long = "regexp", action = clap::ArgAction::Append)]
    regexps: Vec<String>,

    #[arg(value_name = "PATH", action = clap::ArgAction::Append)]
    paths: Vec<PathBuf>,

    #[arg(short = 'n', long)]
    line_number: bool,

    #[arg(short = 'i', long)]
    ignore_case: bool,

    #[arg(short = 'S', long)]
    smart_case: bool,

    #[arg(short = 'v', long)]
    invert_match: bool,

    #[arg(short = 'w', long)]
    word_regexp: bool,

    #[arg(short = 'l', long)]
    files_with_matches: bool,

    #[arg(short = 'c', long)]
    count: bool,

    #[arg(short = 'u', action = clap::ArgAction::Count)]
    unrestricted: u8,

    #[arg(long)]
    color: Option<String>,

    #[arg(long)]
    heading: Option<bool>,

    #[arg(short = 'a', long)]
    text: bool,
}

struct Matcher {
    re: Regex,
}

impl Matcher {
    fn new(pattern: &str, ignore_case: bool, smart_case: bool) -> anyhow::Result<Self> {
        let mut ic = ignore_case;
        if smart_case {
            if !pattern.chars().any(|c| c.is_uppercase()) {
                ic = true;
            }
        }
        let re = regex::RegexBuilder::new(pattern)
            .case_insensitive(ic)
            .build()?;
        Ok(Matcher { re })
    }
}

fn main() -> anyhow::Result<()> {
    let args = Args::parse();

    let mut patterns = args.regexps.clone();
    if let Some(p) = args.pattern {
        patterns.push(p);
    }

    if patterns.is_empty() {
        // rg requires a pattern unless some other flags are used
        // for now just return error
        return Ok(());
    }

    // Combine patterns with |
    let combined_pattern = patterns.iter().map(|p| format!("({})", p)).collect::<Vec<_>>().join("|");
    let mut final_pattern = combined_pattern;
    if args.word_regexp {
        final_pattern = format!(r"\b({})\b", final_pattern);
    }

    let matcher = Matcher::new(&final_pattern, args.ignore_case, args.smart_case)?;

    let mut paths = args.paths.clone();
    if paths.is_empty() {
        if atty::is(atty::Stream::Stdin) {
            paths.push(PathBuf::from("."));
        } else {
            // Search stdin
            return search_stdin(&matcher, &args);
        }
    }

    let mut exit_code = 1;
    let mut error_occurred = false;

    let use_color = match args.color.as_deref() {
        Some("always") => true,
        Some("never") => false,
        _ => atty::is(atty::Stream::Stdout),
    };

    let multiple_files = paths.len() > 1 || (paths.len() == 1 && paths[0].is_dir());

    for path in paths {
        if path.is_file() {
            match search_file(&path, &matcher, &args, use_color, multiple_files) {
                Ok(matched) => if matched && exit_code != 2 { exit_code = 0; },
                Err(e) => {
                    eprintln!("rg: {}: {}", path.display(), e);
                    exit_code = 2;
                    error_occurred = true;
                }
            }
        } else if path.is_dir() {
            let walk = WalkDir::new(path)
                .into_iter()
                .filter_entry(|e| {
                    if args.unrestricted >= 2 { return true; }
                    !is_hidden(e)
                });

            for entry in walk {
                match entry {
                    Ok(entry) => {
                        if entry.file_type().is_file() {
                            match search_file(entry.path(), &matcher, &args, use_color, true) {
                                Ok(matched) => if matched && exit_code != 2 { exit_code = 0; },
                                Err(e) => {
                                    eprintln!("rg: {}: {}", entry.path().display(), e);
                                    exit_code = 2;
                                    error_occurred = true;
                                }
                            }
                        }
                    }
                    Err(e) => {
                        eprintln!("rg: {}", e);
                        exit_code = 2;
                        error_occurred = true;
                    }
                }
            }
        } else {
            eprintln!("rg: {}: No such file or directory (os error 2)", path.display());
            exit_code = 2;
            error_occurred = true;
        }
    }

    if error_occurred {
        std::process::exit(2);
    }
    std::process::exit(exit_code);
}

fn is_hidden(entry: &walkdir::DirEntry) -> bool {
    entry.file_name()
         .to_str()
         .map(|s| s.starts_with('.') && s != "." && s != "..")
         .unwrap_or(false)
}

fn search_stdin(matcher: &Matcher, args: &Args) -> anyhow::Result<()> {
    let stdin = io::stdin();
    let mut reader = BufReader::new(stdin.lock());
    let mut matched = false;
    let mut line_num = 1;
    let mut line = String::new();

    while reader.read_line(&mut line)? > 0 {
        if line.ends_with('\n') { line.pop(); }
        if line.ends_with('\r') { line.pop(); }

        if matcher.re.is_match(&line) != args.invert_match {
            matched = true;
            if args.files_with_matches {
                // For stdin, what do we print? original rg prints "(standard input)"
                println!("(standard input)");
                return Ok(());
            }
            // ... print match ...
        }
        line.clear();
        line_num += 1;
    }
    std::process::exit(if matched { 0 } else { 1 })
}

fn search_file(path: &Path, matcher: &Matcher, args: &Args, use_color: bool, show_filename: bool) -> anyhow::Result<bool> {
    let mut file = File::open(path)?;

    if !args.text && args.unrestricted < 3 {
        let mut buffer = [0u8; 1024];
        let n = file.read(&mut buffer)?;
        if buffer[..n].contains(&0) {
            // Check if it matches
            // We should ideally search the whole file, but for now...
            return Ok(false); 
        }
        // Re-open or seek to start
        file = File::open(path)?;
    }

    let reader = BufReader::new(file);
    let mut matched_in_file = false;
    let mut match_count = 0;

    for (idx, line) in reader.lines().enumerate() {
        let line = match line {
            Ok(l) => l,
            Err(_) => continue,
        };

        if matcher.re.is_match(&line) != args.invert_match {
            matched_in_file = true;
            match_count += 1;
            if args.files_with_matches {
                println!("{}", path.display());
                return Ok(true);
            }
            if args.count {
                continue;
            }

            let mut output = String::new();
            if show_filename {
                if use_color {
                    output.push_str("\x1b[35m");
                    output.push_str(&path.display().to_string());
                    output.push_str("\x1b[0m:");
                } else {
                    output.push_str(&path.display().to_string());
                    output.push(':');
                }
            }
            if args.line_number {
                if use_color {
                    output.push_str("\x1b[32m");
                    output.push_str(&(idx + 1).to_string());
                    output.push_str("\x1b[0m:");
                } else {
                    output.push_str(&(idx + 1).to_string());
                    output.push(':');
                }
            }

            if use_color && !args.invert_match {
                // Highlight matches
                let mut last_end = 0;
                for mat in matcher.re.find_iter(&line) {
                    output.push_str(&line[last_end..mat.start()]);
                    output.push_str("\x1b[1m\x1b[31m");
                    output.push_str(mat.as_str());
                    output.push_str("\x1b[0m");
                    last_end = mat.end();
                }
                output.push_str(&line[last_end..]);
            } else {
                output.push_str(&line);
            }
            println!("{}", output);
        }
    }

    if args.count && matched_in_file {
        if show_filename {
            println!("{}:{}", path.display(), match_count);
        } else {
            println!("{}", match_count);
        }
    }

    Ok(matched_in_file)
}
EOF
"}

