fn main() -> anyhow::Result<()> {
    let args = Args::parse();

    let mut patterns = args.regexps.clone();
    if let Some(p) = args.pattern {
        patterns.push(p);
    }

    if patterns.is_empty() {
        // rg requires a pattern unless some other flags are used
        // for now just return error
        return Ok(());
    }

    // Combine patterns with |
    let combined_pattern = patterns.iter().map(|p| format!("({})", p)).collect::<Vec<_>>().join("|");
    let mut final_pattern = combined_pattern;
    if args.word_regexp {
