{"command":"cat <<'EOF' > main.go
package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

type Config struct {
	Pattern      *regexp.Regexp
	LineNumber   bool
	IgnoreCase   bool
	InvertMatch  bool
	WordRegexp   bool
	FilesMatches bool
	Unrestricted int
	Color        bool
	Heading      bool
	ShowFilename bool
}

func main() {
	args := os.Args[1:]
	if len(args) == 0 {
		return
	}

	config := Config{
		Color: true, // Default to true for now
	}

	var patterns []string
	var paths []string

	for i := 0; i < len(args); i++ {
		arg := args[i]
		if strings.HasPrefix(arg, "-") {
			switch arg {
			case "-n", "--line-number":
				config.LineNumber = true
			case "-i", "--ignore-case":
				config.IgnoreCase = true
			case "-v", "--invert-match":
				config.InvertMatch = true
			case "-w", "--word-regexp":
				config.WordRegexp = true
			case "-l", "--files-with-matches":
				config.FilesMatches = true
			case "-u":
				config.Unrestricted++
			case "-uu":
				config.Unrestricted = 2
			case "-uuu":
				config.Unrestricted = 3
			case "--color":
				i++
				if i < len(args) {
					config.Color = args[i] == "always"
				}
			}
		} else {
			if patterns == nil {
				patterns = append(patterns, arg)
			} else {
				paths = append(paths, arg)
			}
		}
	}

	if len(patterns) == 0 {
		return
	}

	patternStr := patterns[0]
	if config.WordRegexp {
		patternStr = "\\b" + patternStr + "\\b"
	}
	if config.IgnoreCase {
		patternStr = "(?i)" + patternStr
	}

	re, err := regexp.Compile(patternStr)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error compiling regex: %v\n", err)
		os.Exit(2)
	}
	config.Pattern = re

	if len(paths) == 0 {
		paths = append(paths, ".")
	}

	config.ShowFilename = len(paths) > 1 || isDir(paths[0])

	exitCode := 1
	for _, path := range paths {
		err := filepath.Walk(path, func(p string, info os.FileInfo, err error) error {
			if err != nil {
				fmt.Fprintf(os.Stderr, "rg: %s: %v\n", p, err)
				return nil
			}
			if !info.IsDir() {
				if config.Unrestricted < 2 && isHidden(p) {
					return nil
				}
				matched, err := searchFile(p, config)
				if err != nil {
					fmt.Fprintf(os.Stderr, "rg: %s: %v\n", p, err)
					return nil
				}
				if matched {
					exitCode = 0
				}
			}
			return nil
		})
		if err != nil {
			fmt.Fprintf(os.Stderr, "rg: %v\n", err)
		}
	}

	os.Exit(exitCode)
}

func isDir(path string) bool {
	info, err := os.Stat(path)
	return err == nil && info.IsDir()
}

func isHidden(path string) bool {
	base := filepath.Base(path)
	return strings.HasPrefix(base, ".") && base != "." && base != ".."
}

func searchFile(path string, config Config) (bool, error) {
	file, err := os.Open(path)
	if err != nil {
		return false, err
	}
	defer file.Close()

	// Binary check
	if config.Unrestricted < 3 {
		buf := make([]byte, 1024)
		n, _ := file.Read(buf)
		for i := 0; i < n; i++ {
			if buf[i] == 0 {
				return false, nil
			}
		}
		file.Seek(0, 0)
	}

	scanner := bufio.NewScanner(file)
	matched := false
	lineNum := 0
	for scanner.Scan() {
		lineNum++
		line := scanner.Text()
		isMatch := config.Pattern.MatchString(line)
		if isMatch != config.InvertMatch {
			matched = true
			if config.FilesMatches {
				fmt.Println(path)
				return true, nil
			}

			var output strings.Builder
			if config.ShowFilename {
				if config.Color {
					output.WriteString("\x1b[35m")
					output.WriteString(path)
					output.WriteString("\x1b[0m:")
				} else {
					output.WriteString(path)
					output.WriteString(":")
				}
			}
			if config.LineNumber {
				if config.Color {
					output.WriteString("\x1b[32m")
					output.WriteString(fmt.Sprintf("%d", lineNum))
					output.WriteString("\x1b[0m:")
				} else {
					output.WriteString(fmt.Sprintf("%d", lineNum))
					output.WriteString(":")
				}
			}

			if config.Color && !config.InvertMatch {
				lastIdx := 0
				indices := config.Pattern.FindAllStringIndex(line, -1)
				for _, loc := range indices {
					output.WriteString(line[lastIdx:loc[0]])
					output.WriteString("\x1b[1m\x1b[31m")
					output.WriteString(line[loc[0]:loc[1]])
					output.WriteString("\x1b[0m")
					lastIdx = loc[1]
				}
				output.WriteString(line[lastIdx:])
			} else {
				output.WriteString(line)
			}
			fmt.Println(output.String())
		}
	}

	return matched, scanner.Err()
}
EOF
"}

