					config.Color = args[i] == "always"
				}
			} else if arg == "-e" || arg == "--regexp" {
				i++
				if i < len(args) {
					patternStrings = append(patternStrings, args[i])
				}
			} else if arg == "-f" || arg == "--file" {
				i++
				if i < len(args) {
					lines := loadFileLines(args[i])
					patternStrings = append(patternStrings, lines...)
				}
			} else if arg == "-F" || arg == "--fixed-strings" {
				config.FixedStrings = true
			} else if arg == "--version" || arg == "-V" {
				fmt.Println("ripgrep 14.1.1")
				return
			} else if arg == "--help" || arg == "-h" {
				fmt.Println("USAGE: rg [OPTIONS] PATTERN [PATH ...]")
				return
			}
		} else {
			if len(patternStrings) == 0 {
				patternStrings = append(patternStrings, arg)
			} else {
				paths = append(paths, arg)
			}
		}
	}

	if len(patternStrings) == 0 {
		return
	}

	for _, ps := range patternStrings {
		p := ps
		if config.FixedStrings {
			p = regexp.QuoteMeta(p)
		}
		if config.WordRegexp {
			p = "\\b(?:" + p + ")\\b"
		}
		if config.IgnoreCase {
			p = "(?i)" + p
		}
		re, err := regexp.Compile(p)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error compiling regex: %v\n", err)
			os.Exit(2)
		}
		config.Patterns = append(config.Patterns, re)
	}

	if len(paths) == 0 {
		paths = append(paths, ".")
	}

	config.ShowFilename = len(paths) > 1
	for _, p := range paths {
		if isDir(p) {
			config.ShowFilename = true
			break
		}
	}

	exitCode := 1
	hasError := false

	type ignoreSet []string
	ignores := make(map[string]ignoreSet)

	for _, startPath := range paths {
		err := filepath.Walk(startPath, func(path string, info os.FileInfo, err error) error {
			if err != nil {
				fmt.Fprintf(os.Stderr, "rg: %s: %v\n", path, err)
				hasError = true
				return nil
			}

			if config.Unrestricted < 2 && path != startPath {
				if isHidden(path) {
					if info.IsDir() {
						return filepath.SkipDir
					}
					return nil
				}
			}

			if config.Unrestricted < 1 {
				dir := filepath.Dir(path)
				if _, ok := ignores[dir]; !ok {
					ignores[dir] = loadGitignore(filepath.Join(dir, ".gitignore"))
				}
				for _, ip := range ignores[dir] {
					if matched, _ := filepath.Match(ip, filepath.Base(path)); matched {
						if info.IsDir() {
							return filepath.SkipDir
						}
						return nil
					}
				}
			}

			if !info.IsDir() {
				matched, err := searchFile(path, config)
				if err != nil {
					fmt.Fprintf(os.Stderr, "rg: %s: %v\n", path, err)
					hasError = true
					return nil
				}
				if matched {
					if exitCode != 2 {
						exitCode = 0
					}
				}
			}
			return nil
		})
		if err != nil {
			hasError = true
		}
	}

	if hasError {
		os.Exit(2)
	}
	os.Exit(exitCode)
}

func loadFileLines(filename string) []string {
	var lines []string
	file, err := os.Open(filename)
	if err != nil {
		return nil
	}
	defer file.Close()
	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		lines = append(lines, scanner.Text())
	}
	return lines
}

func loadGitignore(filename string) []string {
	var patterns []string
	file, err := os.Open(filename)
	if err != nil {
		return nil
	}
	defer file.Close()
	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		patterns = append(patterns, line)
	}
	return patterns
}

func isDir(path string) bool {
	info, err := os.Stat(path)
	return err == nil && info.IsDir()
}

func isHidden(path string) bool {
	base := filepath.Base(path)
	return strings.HasPrefix(base, ".") && base != "." && base != ".."
}

func attyIsStdout() bool {
	fi, err := os.Stdout.Stat()
	if err != nil {
		return false
	}
	return (fi.Mode() & os.ModeCharDevice) != 0
}

func searchFile(path string, config Config) (bool, error) {
	file, err := os.Open(path)
	if err != nil {
		return false, err
	}
	defer file.Close()

	if config.Unrestricted < 3 {
		buf := make([]byte, 1024)
		n, _ := file.Read(buf)
		for i := 0; i < n; i++ {
			if buf[i] == 0 {
				return false, nil
			}
		}
		file.Seek(0, 0)
	}

	scanner := bufio.NewScanner(file)
	matchedInFile := false
	lineNum := 0
	for scanner.Scan() {
		lineNum++
		line := scanner.Text()

		isMatch := false
		for _, re := range config.Patterns {
			if re.MatchString(line) {
				isMatch = true
				break
			}
		}

		if isMatch != config.InvertMatch {
			matchedInFile = true
			if config.FilesMatches {
				fmt.Println(path)
				return true, nil
			}

			var output strings.Builder
			if config.ShowFilename {
				if config.Color {
					output.WriteString("\x1b[0m\x1b[35m")
					output.WriteString(path)
					output.WriteString("\x1b[0m:")
				} else {
					output.WriteString(path)
					output.WriteString(":")
				}
			}
			if config.LineNumber {
				if config.Color {
					output.WriteString("\x1b[0m\x1b[32m")
					output.WriteString(fmt.Sprintf("%d", lineNum))
					output.WriteString("\x1b[0m:")
				} else {
					output.WriteString(fmt.Sprintf("%d", lineNum))
					output.WriteString(":")
				}
			}

			if config.Color && !config.InvertMatch {
				lastIdx := 0
				var firstRe *regexp.Regexp
				for _, re := range config.Patterns {
					if re.MatchString(line) {
						firstRe = re
						break
					}
				}

				if firstRe != nil {
					indices := firstRe.FindAllStringIndex(line, -1)
					for _, loc := range indices {
						output.WriteString(line[lastIdx:loc[0]])
						output.WriteString("\x1b[0m\x1b[1m\x1b[31m")
						output.WriteString(line[loc[0]:loc[1]])
						output.WriteString("\x1b[0m")
						lastIdx = loc[1]
					}
					output.WriteString(line[lastIdx:])
				} else {
					output.WriteString(line)
				}
			} else {
				output.WriteString(line)
			}
			fmt.Println(output.String())
		}
	}

	return matchedInFile, scanner.Err()
}
